import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    orders_info = {}  # id -> dict(side, price, remaining, status, arrival)

    for arrival, o in enumerate(orders):
        typ = o[0]
        if typ == 'cancel':
            oid = o[1]
            info = orders_info.get(oid)
            if info and info['status'] == 'resting':
                info['status'] = 'cancelled'
            continue

        oid = o[1]
        side = o[2]
        if typ == 'market':
            qty = o[3]
            price_limit = None
        else:
            price = o[3]
            qty = o[4]
            price_limit = price

        info = {
            'side': side,
            'price': price_limit,
            'remaining': qty,
            'status': 'active',
            'arrival': arrival
        }
        orders_info[oid] = info

        opp_heap = sell_heap if side == 'buy' else buy_heap

        while info['remaining'] > 0 and opp_heap:
            top = opp_heap[0]
            if side == 'buy':
                neg_price, opp_arrival, opp_id = top
                opp_price = -neg_price
            else:
                opp_price, opp_arrival, opp_id = top

            opp_info = orders_info.get(opp_id)
            if opp_info is None or opp_info['status'] != 'resting' or opp_info['remaining'] <= 0:
                heapq.heappop(opp_heap)
                continue

            if price_limit is not None:
                if side == 'buy' and opp_price > price_limit:
                    break
                if side == 'sell' and opp_price < price_limit:
                    break

            trade_qty = min(info['remaining'], opp_info['remaining'])
            if side == 'buy':
                trades.append([oid, opp_id, opp_price, trade_qty])
            else:
                trades.append([opp_id, oid, opp_price, trade_qty])

            info['remaining'] -= trade_qty
            opp_info['remaining'] -= trade_qty

            if opp_info['remaining'] == 0:
                opp_info['status'] = 'done'
                heapq.heappop(opp_heap)

        if typ == 'limit' and info['remaining'] > 0:
            info['status'] = 'resting'
            if side == 'buy':
                heapq.heappush(buy_heap, (-price_limit, arrival, oid))
            else:
                heapq.heappush(sell_heap, (price_limit, arrival, oid))
        else:
            if info['remaining'] == 0:
                info['status'] = 'done'
            else:
                info['status'] = 'discarded'

    return trades

